@startuml

class User {
  +id : long
  +name : string
  +address : string
  +birthday : date
}

class BusinessOwner extends User {
  +linkedinAccount : string
}

class HungryCustomer extends User {
  +deliveryAddress : string
}

class Entertainer extends User {
  +stageName : string
  +bio : string
  +pricePer30Minutes : float
}

class PizzaRestaurant {
  +zipCode : string
  +address : string
  +phoneNumber : string
  +website : string
  +openingHours : string
}

class Pizza {
  +name : string
  +crustStructure : string
  +price : double
}

class Order {
  +id : long
  +placedDateTime : datetime
  +latestDeliveryTime : time
  +numberOfPeople : int
}

class EntertainmentOrder extends Order {
  +entertainmentType : string
  +duration : int
}

class EntertainerAvailability {
  +day : string
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
PizzaRestaurant "1" -- "*" EntertainerAvailability : has
Entertainer "1" -- "*" EntertainerAvailability : indicates availability
Entertainer "0..*" -- "0..*" PizzaRestaurant : wants to work with

HungryCustomer "1" -- "*" Order : makes
Order "*" -- "1..*" Pizza : contains

Entertainer "1" -- "0..*" EntertainmentOrder : fulfills

@enduml

